"use client";

import { useState, useMemo } from "react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, addDays } from "date-fns";
import { nl } from "date-fns/locale"; 
import { X, ChevronLeft, ChevronRight, Clock } from "lucide-react";
import { createCalendarItem } from "@/app/actions/task-actions";
import { useRouter } from "next/navigation";

export default function CalendarClient({ initialTasks = [] }: { initialTasks: any[] }) {
  const router = useRouter();
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  
  // Form State (iPhone Tarzı Aralık)
  const [loading, setLoading] = useState(false);
  const [title, setTitle] = useState("");
  const [startTime, setStartTime] = useState("09:00");
  const [endTime, setEndTime] = useState("10:00");
  const [type, setType] = useState("agenda");

  // VERİLERİ EKRANA BASMA MANTIĞI (HATASIZ)
  const taskMap = useMemo(() => {
    const map: any = {};
    initialTasks.forEach((item) => {
      if (item.startDatetime) {
        const d = new Date(item.startDatetime);
        // DB'deki tarihi yerel gün formatına ("2024-05-20") çeviriyoruz
        const dateKey = format(d, "yyyy-MM-dd");
        if (!map[dateKey]) map[dateKey] = [];
        map[dateKey].push(item);
      }
    });
    return map;
  }, [initialTasks]);

  const handleSave = async () => {
    if (!title || !selectedDate) return;
    setLoading(true);

    try {
      const res = await createCalendarItem({
        titel: title,
        documentType: type,
        datum: format(selectedDate, "yyyy-MM-dd"),
        startTime,
        endTime
      });

      if (res.success) {
        setTitle("");
        setSelectedDate(null);
        router.refresh();
        setTimeout(() => window.location.reload(), 300);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-[1400px] mx-auto p-4 text-white">
      {/* Header */}
      <div className="flex justify-between items-center mb-6 bg-[#1a1a1a] p-4 rounded-2xl border border-white/5">
        <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="text-fuchsia-500 cursor-pointer"><ChevronLeft size={32}/></button>
        <h2 className="text-2xl font-black uppercase italic tracking-tighter">
          {format(currentMonth, "MMMM yyyy", { locale: nl })}
        </h2>
        <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="text-fuchsia-500 cursor-pointer"><ChevronRight size={32}/></button>
      </div>

      {/* Takvim Grid */}
      <div className="grid grid-cols-7 border border-white/10 rounded-[32px] overflow-hidden bg-[#0a0a0a] shadow-2xl">
        {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map(d => (
          <div key={d} className="bg-white/5 py-4 text-center text-[10px] font-black text-white/20 uppercase tracking-widest">{d}</div>
        ))}
        {(() => {
          const days = [];
          let day = startOfWeek(startOfMonth(currentMonth), { weekStartsOn: 1 });
          const endDate = endOfWeek(endOfMonth(currentMonth), { weekStartsOn: 1 });

          while (day <= endDate) {
            const dateKey = format(day, "yyyy-MM-dd");
            const dayTasks = taskMap[dateKey] || [];
            const isCurrentMonth = isSameMonth(day, currentMonth);

            days.push(
              <div 
                key={day.toString()} 
                onClick={() => setSelectedDate(day)}
                className={`min-h-[150px] border border-white/5 p-3 hover:bg-white/[0.03] transition-all cursor-pointer relative ${!isCurrentMonth ? "opacity-10" : ""}`}
              >
                <div className="text-xs font-mono text-teal-500/40 mb-2">{format(day, "d")}</div>
                <div className="space-y-1.5">
                  {dayTasks.map((t: any) => (
                    <div key={t.id} className="text-[10px] p-2 bg-fuchsia-600/10 border-l-2 border-fuchsia-500 rounded-r text-white shadow-lg">
                      <div className="font-bold truncate">{t.title}</div>
                      <div className="text-[8px] opacity-50 font-mono">
                        {format(new Date(t.startDatetime), "HH:mm")} - {format(new Date(t.endDatetime), "HH:mm")}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            );
            day = addDays(day, 1);
          }
          return days;
        })()}
      </div>

      {/* iPhone Style Modal (Zaman Aralıklı) */}
      {selectedDate && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-md p-4">
          <div className="bg-[#1c1c1e] w-full max-w-sm rounded-[40px] p-8 border border-white/10 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold italic">Etkinlik Ekle</h3>
              <button onClick={() => setSelectedDate(null)} className="text-white/20 hover:text-white transition-colors cursor-pointer"><X /></button>
            </div>
            
            <div className="space-y-6">
              <input 
                placeholder="Başlık" 
                value={title} onChange={(e) => setTitle(e.target.value)}
                className="w-full bg-[#2c2c2e] p-5 rounded-2xl text-white outline-none focus:ring-2 ring-fuchsia-500/50"
              />
              
              <div className="bg-[#2c2c2e] rounded-2xl divide-y divide-white/5">
                <div className="flex justify-between p-5 items-center">
                  <span className="text-sm font-medium text-white/40">Başlangıç</span>
                  <input type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} className="bg-[#3a3a3c] rounded-lg p-2 text-sm text-white font-mono outline-none border-none" />
                </div>
                <div className="flex justify-between p-5 items-center">
                  <span className="text-sm font-medium text-white/40">Bitiş</span>
                  <input type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)} className="bg-[#3a3a3c] rounded-lg p-2 text-sm text-white font-mono outline-none border-none" />
                </div>
              </div>

              <button 
                onClick={handleSave}
                disabled={loading || !title}
                className="w-full bg-white text-black font-black py-5 rounded-[20px] uppercase text-xs tracking-[0.2em] shadow-xl active:scale-95 transition-all disabled:opacity-20"
              >
                {loading ? "Kaydediliyor..." : "Ekle"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}